import { resolve } from "node:path";

const result = await Bun.build({
  entrypoints: [resolve(import.meta.dir, "../../../src/sdk/client.ts")],
  target: "browser",
  format: "esm",
  minify: true,
});
if (!result.success) throw new Error(result.logs.join("\n"));
await Bun.write(
  new URL("../src/lib/site/sdk-bundle.ts", import.meta.url),
  "// Generated by bun scripts/build-site-sdk.ts\nexport const siteSdk = " +
    JSON.stringify(await result.outputs[0]!.text()) +
    ";\n",
);
